create table public.body_measurements (id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,measured_at date not null default current_date,weight_kg numeric(6,2) check(weight_kg>0),height_cm numeric(5,1) check(height_cm>0),waist_cm numeric(5,1) check(waist_cm>0),chest_cm numeric(5,1) check(chest_cm>0),arm_cm numeric(5,1) check(arm_cm>0),notes text not null default '',created_at timestamptz not null default now());create index body_measurements_owner_date_idx on public.body_measurements(owner_id,measured_at desc);alter table public.body_measurements enable row level security;create policy "own body measurements" on public.body_measurements for all to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
